<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\{Cart,CartItem,Product};use Illuminate\Http\Request;
class CartController extends Controller{private function cart($u){return Cart::firstOrCreate(['customer_id'=>$u->id]);}public function show(Request $r){return $this->cart($r->user())->load('items.product');}public function store(Request $r){$d=$r->validate(['product_id'=>'required|uuid','quantity'=>'required|integer|min:1']);$cart=$this->cart($r->user());$i=$cart->items()->firstOrNew(['product_id'=>$d['product_id']]);$i->quantity=($i->quantity??0)+$d['quantity'];$i->save();return $cart->load('items.product');}public function update(Request $r,Product $product){$d=$r->validate(['quantity'=>'required|integer|min:1']);$cart=$this->cart($r->user());$cart->items()->where('product_id',$product->id)->update(['quantity'=>$d['quantity']]);return $cart->load('items.product');}public function destroy(Request $r,Product $product){$this->cart($r->user())->items()->where('product_id',$product->id)->delete();return $this->show($r);}}
